script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const ruleData = api.data.rule_management_dmc.ruleData;
    if (ruleData && ruleData.archive && ruleData.archive.enable_data_destroy) {
        return "";
    }

    return "non-interactable";
}

